///
/// `on_event` is invoked (on the GTK main thread) with the shared ring whenever
/// the renderer wrote a raw input; the app drains the ring's event queue itself
/// (`RingTransport::drain_events`) and may re-emit a new frame.
///

/// A generic CSS family for a `FONT_DESIGN` code (Default → the renderer's UI
/// font, i.e. no override).
fn font_design_family(code: u8) -> Option<&'static str> {
    match code {
        1 => Some("serif"),
        2 => Some("sans-serif"),
        3 => Some("ui-monospace, SFMono-Regular, Menlo, monospace"),
