    pub fn attributed(&mut self, value: impl Into<pathland_core::AttributedString>) -> &mut Self {
        let value = value.into();
        self.text = value.text().to_string();
        self.binding = None;
        self.attributed = Some(value);
        self.attributed_binding = None;
        self
    }

