fn renders_attributed_text_as_spans_and_links() {
    let value = pathland_core::AttributedString::new(
        "Hi",
        vec![pathland_core::StyleRun::new(0, 2).bold()],
        vec![pathland_core::LinkRun::new(1, 2, "x")],
    )
    .unwrap();
